<?php
namespace App\Http\Controllers; use App\Models\Category; use Illuminate\Http\Request; class CategoryController extends Controller {public function index(){return view('categories.index',['categories'=>Category::withCount('items')->orderBy('name')->get()]);} public function store(Request $r){$d=$r->validate(['name'=>'required|string|max:255|unique:categories,name','description'=>'nullable|string']);Category::create($d);return back()->with('success','Category save ho gayi.');} public function destroy(Category $category){if($category->items()->exists())return back()->with('error','Pehle category ke items change karein.');$category->delete();return back()->with('success','Category delete ho gayi.');}}
